            "kind": "p",
            "text": "Угол равен [[A=\\tan^{-1}(4/3)\\approx53.13^\\circ]]. Вертикальная высота больше горизонтального расстояния, поэтому отношение превышает 1. Пример объясняет геометрию и не устанавливает, безопасно ли установлена лестница."
