        "La tangente est le rapport des deux côtés : divisez le côté opposé par le côté adjacent et vous avez décrit combien d’unités de montée verticale accompagnent chaque unité de distance horizontale. La formule [[\\tan(A)=a/b]] ne nécessite que deux mesures, la réponse est toujours un nombre sans dimension qui peut se situer en dessous, à, ou au-dessus de 1, et elle croît à mesure que l’angle de référence grandit. Lorsqu’un côté manquant est nécessaire, [[a=b\\tan(A)]] retrouve le côté opposé ; lorsque l’angle est nécessaire, [[A=\\tan^{-1}(a/b)]] le retrouve. Rampe, toit, échelle ou 3-4-5 de manuel, la méthode ne change jamais : identifiez le côté opposé, identifiez le côté adjacent, divisez, et vérifiez avec le contrôle du rapport positif."
