            "text": "Die Meter kürzen sich heraus und lassen eine reine Zahl übrig. Dasselbe Verhältnis erhält man aus 300 cm und 400 cm, weil die Einheitenänderung beide Seiten gleichermaßen betrifft. Die einzige Voraussetzung ist, dass beide Messungen kompatible Einheiten verwenden: Meter mit Zentimetern zu mischen erzeugt eine bedeutungslose Zahl, während eine vorherige Umrechnung das Verhältnis ehrlich hält."
