            "text": "[[\\tan(A)=0.75]] bedeutet, dass die Gegenkathete das 0.75-fache der Ankathete beträgt, also 75 Einheiten vertikalen Anstiegs auf je 100 Einheiten horizontalen Laufs in derselben geradlinigen Geometrie. Stellen Sie sich ein Dach vor, das auf je 100 cm horizontalen Laufs 75 cm ansteigt: Genau das beschreibt 0.75. Es bedeutet nicht, dass der Winkel [[0.75^\\circ]] beträgt; Verhältnis und Winkel sind verschiedene Größen, und sie zu verwechseln ist einer der häufigsten Fehler in der Trigonometrie."
