            "text": "[[\\tan(A)=1]] bedeutet [[a=b]]: Gegenkathete und Ankathete sind gleich lang. Ein gleichschenkliges rechtwinkliges Dreieck hat zwei gleiche Katheten, und weil sich die beiden spitzen Winkel die 90 Grad gleichmäßig teilen müssen, beträgt jeder [[45^\\circ]]:"
