            "text": "Im Gegensatz zu Sinus und Kosinus hat der Tangens für spitze Winkel keine obere Grenze. Wenn die Gegenkathete länger wird als die Ankathete, überschreitet das Verhältnis problemlos die 1. Mit [[a=6]] und [[b=3]]:"
