    "faqs": [
      {
        "question": "Wie lautet die Tangensverhältnis-Formel für ein rechtwinkliges Dreieck?",
        "answer": "tan(A) = a / b: Dividieren Sie die Gegenkathete a durch die Ankathete b. Bei einer Gegenkathete von 3 cm und einer Ankathete von 4 cm lautet das Ergebnis 3/4 = 0.75. Diese Dezimalzahl ist die vollständige Antwort, ein dimensionsloses Verhältnis, kein Winkel."
      },
      {
        "question": "Wie berechnet man den Tangens aus zwei Seitenlängen?",
        "answer": "Legen Sie den Bezugswinkel A fest, messen Sie die Gegenkathete a und die Ankathete b in derselben Einheit, vergewissern Sie sich, dass beide positiv sind, und dividieren Sie dann: tan(A) = a / b. Geben Sie auf dieser Seite die Gegenkathete in das erste Feld und die Ankathete in das zweite ein und klicken Sie dann auf Tangens berechnen."
      },
      {
        "question": "Warum verwendet der Tangens nicht die Hypotenuse?",
        "answer": "Der Tangens vergleicht die beiden senkrechten Katheten direkt: vertikal gegen horizontal. Die Hypotenuse fügt diesem Vergleich keine neue Information hinzu, daher benötigt die eigentliche Formel nur Gegenkathete und Ankathete. Der Satz des Pythagoras kann die Hypotenuse später zurückgewinnen, wenn eine andere Berechnung sie benötigt."
      },
      {
        "question": "Kann der Tangens größer als 1 sein?",
        "answer": "Ja. Der Tangens hat für spitze Winkel keine obere Grenze. Wenn die Gegenkathete länger als die Ankathete ist, überschreitet das Verhältnis die 1: Mit a = 6 und b = 3 ist tan(A) = 6/3 = 2. Ein Ergebnis über 1 ist mathematisch gültig und weist nicht auf einen Rechnerfehler hin."
      },
      {
        "question": "Was bedeutet ein Tangenswert von 0.75?",
        "answer": "Die Gegenkathete beträgt 75 Prozent der Ankathete. In einem 3-4-5-Dreieck ist die dem Winkel A gegenüberliegende Seite 3 Einheiten lang, während die Seite neben dem Winkel A 4 Einheiten lang ist, also tan(A) = 3/4 = 0.75. Es beschreibt die Dreiecksform und ist kein Winkel von 0.75 Grad."
      },
      {
        "question": "Was ist der Unterschied zwischen Tangens und Kotangens?",
        "answer": "Sie sind Kehrwerte. Der Tangens dividiert die Gegenkathete durch die Ankathete (a/b); der Kotangens dividiert die Ankathete durch die Gegenkathete (b/a). Wenn tan(A) = 0.75, dann ist cot(A) = 1/0.75, etwa 1.3333. Die Bruchreihenfolge ist genau umgekehrt."
      },
      {
        "question": "Wie kann ich einen Winkel aus einem Tangensverhältnis berechnen?",
        "answer": "Wenden Sie den Arkustangens auf das Verhältnis an: A = tan^-1(a/b). Für tan(A) = 0.75 ist A = tan^-1(0.75), etwa 36.87 Grad. Stellen Sie Ihren wissenschaftlichen Taschenrechner zuerst auf den Gradmodus. Der Rechner auf dieser Seite liefert das Verhältnis, nicht den Winkel."
      },
      {
        "question": "Wie kann ich die Gegenkathete mit dem Tangens finden?",
        "answer": "Stellen Sie die Formel um zu a = b * tan(A). Wenn die Ankathete 10 m beträgt und der Winkel A 30 Grad beträgt, ist tan(30 deg) etwa 0.5774, also a = 10 * 0.5774, etwa 5.774 m. Dies ist eine manuelle Umstellung; der Rechner auf dieser Seite liefert das Verhältnis aus Seitenlängen, keine fehlenden Seiten."
      },
      {
        "question": "Wie kann ich die Ankathete mit dem Tangens finden?",
        "answer": "Stellen Sie die Formel um zu b = a / tan(A). Wenn die Gegenkathete 6 m beträgt und der Winkel A 45 Grad beträgt, ist tan(45 deg) = 1, also b = 6/1 = 6 m. Dies ist eine mathematische Umstellung derselben Formel, kein separater Modus des Rechners auf dieser Seite."
      },
      {
        "question": "Ist der Tangens dasselbe wie die Steigung?",
        "answer": "Sie sind eng verwandt. Die Steigung als Anstieg durch Lauf ist derselbe Vergleich, den der Tangens anstellt: vertikale Änderung geteilt durch horizontale Änderung. Ein Straßenbauingenieur, der die Steigung 0.05 aufschreibt, und ein Trigonometrieschüler, der tan(A) = 0.05 aufschreibt, beschreiben dasselbe Verhältnis. Die Begriffe unterscheiden sich durch den Kontext, nicht durch die Mathematik."
      },
      {
        "question": "Was ist der Unterschied zwischen Prozentgefälle und Winkel in Grad?",
        "answer": "Das Prozentgefälle ist das 100-fache des Tangensverhältnisses: Ein 0.05-Tangens ergibt ein 5%-Gefälle. Der Winkel ist der Arkustangens des Verhältnisses: tan^-1(0.05) beträgt etwa 2.86 Grad. Ein 5%-Gefälle ist daher kein 5-Grad-Winkel. Die beiden zu verwechseln ist einer der häufigsten Tangensfehler."
      },
      {
        "question": "Wie wird der Tangens im Bauwesen und in der Vermessung verwendet?",
        "answer": "Der Tangens vergleicht vertikalen Anstieg mit horizontalem Lauf, was genau das ist, was Dachneigung, Rampenneigung, Straßensteigung und Treppensteilheit beschreiben. Vermesser verwenden ihn, um einen Höhenunterschied und eine horizontale Strecke in einen Höhenwinkel umzuwandeln. In jedem Fall bescheinigt das Verhältnis allein niemals statische Sicherheit oder Normkonformität."
      }
    ],
    "faqHeading": "Häufig gestellte Fragen",
