    "conclusion": {
      "h2": "Verwenden Sie das Tangensverhältnis mit Zuversicht",
      "paragraphs": [
        "Der Tangens ist das Verhältnis der beiden Katheten: Dividieren Sie die Gegenkathete durch die Ankathete, und Sie haben beschrieben, wie viele Einheiten vertikalen Anstiegs auf jede Einheit horizontalen Laufs kommen. Die Formel [[\\tan(A)=a/b]] benötigt nur zwei Messungen, die Antwort ist stets eine dimensionslose Zahl, die unter, bei oder über 1 liegen kann, und sie wächst mit wachsendem Bezugswinkel. Wenn eine fehlende Seite benötigt wird, gewinnt [[a=b\\tan(A)]] die Gegenkathete zurück; wenn der Winkel benötigt wird, gewinnt [[A=\\tan^{-1}(a/b)]] ihn zurück. Ob Rampe, Dach, Leiter oder Schulbuch-3-4-5, die Methode ändert sich nie: Gegenkathete identifizieren, Ankathete identifizieren, dividieren und mit der Positivitätsprüfung verifizieren."
      ]
    }
