      "sec-examples": "Esempi passo passo di calcolo della tangente",
      "sec-applications": "Esempi reali di uso del rapporto tangente",
      "sec-angle": "Il rapporto tra tangente e ampiezza dell'angolo",
      "sec-side": "Come trovare il cateto opposto con la tangente",
      "sec-recover": "Come trovare un angolo dal rapporto tangente",
      "sec-mistakes": "Errori comuni nel calcolo della tangente",
