          "<strong>Confondere la tangente con il seno.</strong> La tangente divide il cateto opposto per quello adiacente; il seno divide il cateto opposto per l'ipotenusa. Se l'ipotenusa è al denominatore, la risposta è il seno, non la tangente.",
