          "<strong>Identificare i lati rispetto all'angolo di riferimento sbagliato.</strong> Passando dall'angolo [[A]] all'angolo [[C]] le etichette di opposto e adiacente si scambiano, il che rovescia il rapporto nel suo reciproco.",
